"""Generate all29bearing-stage handoffs from measured native evidence."""
from pathlib import Path
import collections,hashlib,json
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'development/levels/rebuild';OUT=BASE/'terrain-fit-pass'
def main():
    roster=json.loads((BASE/'stage-register.json').read_text())['sites'];flat=json.loads((OUT/'verification/native-route-fit.json').read_text())['sites'];rows=[]
    for site in roster:
        key=site['id'];folder=OUT/site['folder'];path=folder/'construction.json'
        if not path.exists():
            rows.append(dict(id=key,status='RETAIN_MATURE_NATIVE_INDIVIDUAL_BEARING_AUDIT_REQUIRED',next_action='Inspect mature terrain/structure/arrival individually; preserve current source, props and placement contracts.',runtime_accepted=False));continue
        r=json.loads(path.read_text());types=collections.Counter(x['kind'] for x in r['construction']);findings=collections.Counter(x['type'] for x in r['open_findings'])
        rows.append(dict(id=key,status='NATIVE_BEARING_CONSTRUCTION_REVIEW_OPEN',evidence=path.relative_to(ROOT).as_posix(),parts=r['new_parts'],triangles=r['new_triangles'],kinds=dict(types),open_contacts=dict(findings),flat_route_comparison=flat[key],master_replaced=False,runtime_accepted=False))
        text=f"# {key}: terrain bearing construction\n\n{r['new_parts']}new closed parts /{r['new_triangles']}triangles: {dict(types)}. Actual source terrain determines embedded bottoms; source deck undersides determine tops and owning receivers. Perimeter masonry uses the union of exact lowest floor rectangles, never internal room partitions. Timber piles and short explicit bearing beams support actual raised decks/routes; the moored vessel hull is excluded from land foundations.\n\nSource: `{r['source_glb']}`. Original native collision bytes, terrain, source meshes/UVs/image bindings and world poses retained. Source model masters and current map masters remain unchanged. Actual reimported GLB/native parity and independent contact/closed-solid checks pass. These are native construction candidates, not map acceptance.\n\nFlat before/after comparison: {flat[key]['samples']}samples /{flat[key]['baseline_valid']}baseline-valid poses /{flat[key]['baseline_sweep']}qualified sweeps; {flat[key]['new_block']}new blocks /{flat[key]['new_sweep_block']}new sweep failures. Whole flight/path comparisons have no new bearing regressions. Existing terrain/stair failures remain open.\n\nUnfinished contacts: {dict(findings)}. These are withheld construction decisions, not invented ground or silent passes. Build missing real deck meshes, foundation/retaining/rock transitions and low-route support headers; revise the terrain/building relationship where earth overtops existing floors. Preserve actual saved basement punches and the40-space envelope. Complete canonical van arrival, physical containment, water, services/story and native runtime/network/hardware acceptance.\n"
        (folder/'NEXT.md').write_bytes(text.encode())
    report=dict(scope=29,status='BREADTH_BY_STAGE_BEARING_CONSTRUCTION_IN_PROGRESS',sites=rows,source_commit='BOUND_BY_CHECKPOINT_AND_PUBLICATION_RECEIPT',generator_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),limitations='25editable candidates, four mature sources retained. No master replacement, terrain/engineering/runtime acceptance or map unlock.')
    assert len(rows)==29
    (OUT/'roster.json').write_bytes((json.dumps(report,indent=2)+'\n').encode())
    lines=['# Terrain-bearing construction batch','','25editable native candidates retain the prior terrain/structure/model sources and add actual ground-to-floor construction. Four mature maps remain explicitly retained for individual audits.','','| Site | New closed parts | New triangles | New flat pose/sweep failures |','|---|---:|---:|---|']
    for r in rows:
        p=r.get('flat_route_comparison',{});lines.append(f"| {r['id']} | {r.get('parts','Retained')} | {r.get('triangles','Individual audit')} | {p.get('new_block','Not run')} / {p.get('new_sweep_block','Not run')} |")
    lines+=['','## Scope and verification','','- `*/supported-terrain.blend`, `.glb`, `.hcs2`: actual editable/exported construction; original collision records preserved before new parts.','- `*/construction.json`: exact source/hash lineage, every embedded support and owning upper receiver, withheld contacts and current captures.','- `verification/bearing-contact.json`: independent ground/underside rays, owning mesh contact, embed depth, explicit beam attachment, closed outward solids and render/native parity. Rejects17floating reservation-post negatives.','- `verification/export-preservation.json`: every retained exported mesh/UV/image binding/pose within declared quantization.','- `verification/native-route-fit.json`:110409flat samples,98449baseline-valid poses/93321qualified sweeps, zero new blocks.','- `verification/stairs/`:221vertical segments,84complete links,7automatic multi-link chains and2declared cemetery loops in both before/after variants; no new passing-direction regressions. Both variants185/221flights and47/84complete links pass;36flights/37links remain failing.','- `existing-terrain-review.json`: individual current source/geometry/view decisions for all7older terrain candidates. These have not passed the desquareify gate.','','The prior terrain batch exposes mesa WLD-03/L13/segment0 in addition to prior stair failures: the older furnished source passed, but both pre/post bearing terrain composites fail. Record it as terrain fit, not a bearing regression or accepted movement.72actual failed directional poses have contact diagnosis. A missing phase now rejects instead of producing an empty success-looking diagnosis.','','Next: construct real exterior decks where source reservations lack meshes; resolve overall terrain/building/stair relationships, including the7existing terrain sources; add correct low-route headers, cliff/retaining/foundation rims, pier and cave structures, water/bank and physical boundaries. Canonical van arrival is still absent. Existing orange/cyan route strips are construction inputs, not terrain constraints or finished path surfaces. Finish surface/textures, architecture and full runtime/network/hardware gates later.','','No current source master, reusable prop pivot/UV or saved editor punch was overwritten. No editor UI or timed round test. Structural massing, terrain fit, visual acceptance and actual runtime acceptance remain separate.','']
    (OUT/'README.md').write_bytes(('\n'.join(lines)).encode())
    print('Recorded29decisions /25bearing candidates; all acceptance gates remain explicit')
if __name__=='__main__':main()
